1	//! The dependency type declarations project types reference, loaded by name before resolution
2	//! (`PipelineOptions::load_dependencies`, ADR 0010).
3	//!
4	//! A demand is a name a project file imports from a package and uses in a type. The loader resolves the module the
5	//! way the resolver will (`resolve_module_with`), finds the file declaring the name by following re-exports
6	//! (`export *`, `export { a as b } from`, `export * as ns from`, `import x; export { x }`), parses that file, then
7	//! follows the names its declaration references the same way. Only declaring files enter the layer; re-export stubs are
8	//! walked once and their answers kept, in the layer and in a per-package index on disk, so later runs never
9	//! open them. The resolver consults the layer after the project's own data: its import map and named-type index fall
10	//! back to it, re-export answers come from it, and dependency components form a value index for `typeof` that is never
11	//! emitted.
12	
13	use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
14	use std::sync::{Arc, Mutex, OnceLock};
15	use std::time::SystemTime;
16	
17	use camino::{Utf8Path, Utf8PathBuf};
18	use compact_str::CompactString;
19	use dashmap::{DashMap, DashSet};
20	use rustc_hash::{FxBuildHasher, FxHashMap, FxHashSet};
21	use serde::{Deserialize, Serialize};
22	
23	use crate::import_map::ImportResolutionMap;
24	use crate::named_type_index::NamedTypeIndex;
25	use crate::path_key::PathKey;
26	use crate::resolver::{ModuleResolution, ModuleResolvers};
27	use crate::types::options::PipelineOptions;
28	use crate::types::*;
