30	type FxDashMap<K, V> = DashMap<K, V, FxBuildHasher>;
31	type FxDashSet<K> = DashSet<K, FxBuildHasher>;
32	/// The files that augment React which the module a `(scope, specifier)` resolved to leads to, parsed, once the first
33	/// demand of the scope has searched them; incomplete when the search could not read a file, for every demand of the
34	/// scope.
35	type ModuleCell = Arc<OnceLock<Partial<Vec<(Utf8PathBuf, Arc<SourceData>)>>>>;
36	
37	/// A file's data, read and parsed once per load whoever asks first, a failed read included (`Loader::parse_source`).
38	type ParseCell = Arc<OnceLock<Result<Option<Arc<SourceData>>, ReadFailed>>>;
39	
40	/// Whether a file merges declarations into React, and the specifiers it re-exports, in order.
41	type Scan = (bool, Arc<[String]>);
42	
43	/// A [`Scan`] of a file, read once per load (`Loader::augmentation_scan`).
44	type ScanCell = Arc<OnceLock<Result<Option<Scan>, ReadFailed>>>;
45	
46	/// A dependency file that exists but could not be read (a permission, too many open files, an install racing the run):
47	/// what it declares is unknown, not absent. `Loader::read` and `Loader::parse` return it for the one file; every walk
48	/// or search over many files turns it into an incomplete [`Partial`] and goes on with the files it can read.
49	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
50	struct ReadFailed;
51	
52	/// What a walk or search found in the files it could read, and whether it passed one it could not ([`ReadFailed`]).
53	/// An incomplete answer is used by the load that made it, as the best it has, and kept nowhere: not in the loader's
54	/// maps, the layer or the index; the demand it served is not counted as followed, and a lazy session does not memoize
55	/// a component that needed it, so the next load over the layer looks again.
56	#[must_use]
57	#[derive(Debug, Clone, PartialEq, Eq)]
58	struct Partial<T> {
59	    value: T,
60	    incomplete: bool,
61	}
62	
63	impl<T> Partial<T> {
64	    fn complete(value: T) -> Self {
65	        Partial { value, incomplete: false }
66	    }
67	}
68	
69	impl Partial<()> {
70	    /// Nothing, because the one file needed could not be read.
71	    const UNREAD: Partial<()> = Partial { value: (), incomplete: true };
72	    const DONE: Partial<()> = Partial { value: (), incomplete: false };
73	
74	    fn and(self, other: Partial<()>) -> Partial<()> {
75	        Partial { value: (), incomplete: self.incomplete || other.incomplete }
76	    }
77	}
78	
79	/// Why an export lookup's answer may not be kept, gathered over one walk.
80	#[derive(Debug, Default, Clone, Copy)]
81	struct Unkept {
82	    /// The walk met a module already on it (a re-export cycle), so the answer depends on where it entered.
83	    cycle: bool,
84	    /// The walk passed a module it could not read, which may have declared the name.
85	    unread: bool,
86	}
87	
88	impl Unkept {
89	    fn absorb(&mut self, other: Unkept) {
90	        self.cycle |= other.cycle;
91	        self.unread |= other.unread;
92	    }
93	}
94	
95	/// What one probe of a directory found, once it has run (`probe_once`).
96	type ProbeCell = Arc<OnceLock<bool>>;
97	
98	/// `(directory of the importing file, specifier, exported name path)`.
99	type DemandKey = (Box<str>, Box<str>, CompactString);
100	
101	/// A name a file uses from another module: `specifier` as written in `from`, and the exported name path
102	/// (`Accordion.Root` for `RadixPrimitive.Accordion.Root` through `import * as RadixPrimitive`).
103	#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
104	pub(crate) struct Demand {
105	    pub(crate) from: Utf8PathBuf,
106	    pub(crate) specifier: Box<str>,
107	    pub(crate) name: CompactString,
108	}
109	
110	impl Demand {
111	    fn key(&self) -> DemandKey {
112	        let dir = self.from.parent().map_or("", Utf8Path::as_str);
113	        (Box::from(dir), self.specifier.clone(), self.name.clone())
114	    }
115	}
116	
117	/// Why a demand found no declaration.
118	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
119	pub(crate) enum Unresolved {
120	    /// The specifier resolves to nothing.
121	    Unresolvable,
122	    /// The module resolves, but to JavaScript with no declaration file.
123	    NoTypes,
124	    /// The module has types, but none of its exports is the name.
125	    NotExported,
126	}
127	
128	impl Unresolved {
129	    pub(crate) fn describe(self) -> &'static str {
130	        match self {
131	            Unresolved::Unresolvable => "its module could not be resolved",
132	            Unresolved::NoTypes => "its package ships no type declarations",
133	            Unresolved::NotExported => "its package's types do not export it",
134	        }
135	    }
136	}
137	
138	/// A demanded name that panics the loader under `#[cfg(test)]`, to drive the containment path.
139	#[cfg(test)]
140	const DEMAND_PANIC_TEST_NAME: &str = "__DEPENDENCY_PANIC_TEST__";
141	
142	fn is_typescript(path: &Utf8Path) -> bool {
143	    crate::extractor::is_typescript(path.as_std_path())
144	}
