146	// ─── Demands ──────────────────────────────────────────────────────────────────
147	
148	/// Every name `data` uses in a type: references, `typeof` queries, heritage and type arguments, in its interfaces,
149	/// type aliases and component props.
150	fn referenced_names(data: &SourceData, out: &mut FxHashSet<CompactString>) {
151	    for iface in data.interfaces.values() {
152	        interface_refs(iface, out);
153	    }
154	    for alias in data.type_aliases.values() {
155	        alias_refs(alias, out);
156	    }
157	    for mapping in &data.component_mappings {
158	        mapping_refs(mapping, out);
159	    }
160	}
161	
162	fn interface_refs(iface: &CollectedInterface, out: &mut FxHashSet<CompactString>) {
163	    for prop in &iface.props {
164	        type_refs(&prop.collected_type, out);
165	    }
166	    for extends in &iface.extends {
167	        let (name, args) = match extends {
168	            ExtendsRef::SameFile { name, type_args } => (name, type_args),
169	            ExtendsRef::Imported { local_name, type_args, .. } => (local_name, type_args),
170	            ExtendsRef::Builtin { name, type_args, .. } => (name, type_args),
171	        };
172	        out.insert(CompactString::from(name.as_str()));
173	        args.iter().for_each(|arg| type_refs(arg, out));
174	    }
175	}
176	
177	fn alias_refs(alias: &CollectedTypeAlias, out: &mut FxHashSet<CompactString>) {
178	    match alias {
179	        CollectedTypeAlias::Omit { base, keys, .. } | CollectedTypeAlias::Pick { base, keys, .. } => {
180	            type_refs(base, out);
181	            type_refs(keys, out);
182	        }
183	        CollectedTypeAlias::Partial { base, .. } | CollectedTypeAlias::Required { base, .. } => type_refs(base, out),
184	        CollectedTypeAlias::Union { members, .. } | CollectedTypeAlias::Intersection { members, .. } => {
185	            members.iter().for_each(|member| type_refs(member, out));
186	        }
187	        CollectedTypeAlias::Passthrough { target, .. } => type_refs(target, out),
188	        CollectedTypeAlias::LiteralUnion { .. } => {}
189	    }
190	}
191	
192	fn mapping_refs(mapping: &ComponentMapping, out: &mut FxHashSet<CompactString>) {
193	    out.insert(CompactString::from(mapping.props_type_name.as_str()));
194	    mapping.props_type_args.iter().for_each(|arg| type_refs(arg, out));
195	    // A factory call's callback annotation (`make('div', (props: ExternalProps) => ...)`) names types only here.
196	    if let Some(factory_props) = &mapping.factory_props {
197	        type_refs(factory_props, out);
198	    }
199	}
200	
201	fn type_refs(ty: &CollectedType, out: &mut FxHashSet<CompactString>) {
202	    match ty {
203	        CollectedType::Named { name, args } => {
204	            out.insert(name.clone());
205	            args.iter().for_each(|arg| type_refs(arg, out));
206	        }
207	        CollectedType::TypeOf(name) => {
208	            out.insert(name.clone());
209	        }
210	        CollectedType::Union(members)
211	        | CollectedType::Intersection(members)
212	        | CollectedType::TemplateLiteral(members) => members.iter().for_each(|member| type_refs(member, out)),
213	        CollectedType::Tuple(elements) => elements.iter().for_each(|element| type_refs(&element.element_type, out)),
214	        CollectedType::Array(inner) | CollectedType::Readonly(inner) | CollectedType::KeyOf(inner) => {
215	            type_refs(inner, out)
216	        }
217	        CollectedType::AtFile { inner, .. } => type_refs(inner, out),
218	        CollectedType::Object(fields) => field_refs(fields, out),
219	        CollectedType::Callable { signatures, fields } => {
220	            for signature in signatures {
221	                let mut inner = FxHashSet::default();
222	                signature.params.iter().for_each(|param| type_refs(param, &mut inner));
223	                type_refs(&signature.return_type, &mut inner);
224	                out.extend(inner.into_iter().filter(|name| !signature.type_params.contains(name)));
225	            }
226	            field_refs(fields, out);
227	        }
228	        CollectedType::IndexedAccess { obj, key } => {
229	            type_refs(obj, out);
230	            type_refs(key, out);
231	        }
232	        CollectedType::Function { type_params, params, return_type, .. } => {
233	            let mut inner = FxHashSet::default();
234	            params.iter().for_each(|param| type_refs(param, &mut inner));
235	            type_refs(return_type, &mut inner);
236	            out.extend(inner.into_iter().filter(|name| !type_params.contains(name)));
237	        }
238	        CollectedType::Conditional { check, extends_type, true_type, false_type } => {
239	            for part in [check, extends_type, true_type, false_type] {
240	                type_refs(part, out);
241	            }
242	        }
243	        CollectedType::Mapped { param, key_type, value_type, .. } => {
244	            type_refs(key_type, out);
245	            let mut inner = FxHashSet::default();
246	            type_refs(value_type, &mut inner);
247	            out.extend(inner.into_iter().filter(|name| name != param));
248	        }
249	        CollectedType::String
250	        | CollectedType::Number
251	        | CollectedType::Boolean
252	        | CollectedType::Null
253	        | CollectedType::Undefined
254	        | CollectedType::Any
255	        | CollectedType::Never
256	        | CollectedType::Unknown
257	        | CollectedType::Void
258	        | CollectedType::BigInt
259	        | CollectedType::Symbol
260	        | CollectedType::StringLiteral(_)
261	        | CollectedType::NumberLiteral(_)
262	        | CollectedType::BoolLiteral(_)
263	        | CollectedType::BigIntLiteral(_)
264	        | CollectedType::UniqueSymbol
265	        | CollectedType::Raw(_) => {}
266	    }
267	}
268	
269	fn field_refs(fields: &[crate::types::CollectedObjectField], out: &mut FxHashSet<CompactString>) {
270	    fields.iter().for_each(|field| {
271	        type_refs(&field.collected_type, out);
272	        if let Some(key) = &field.index_key {
273	            type_refs(key, out);
274	        }
275	    })
276	}
