278	/// The module and exported name path `reference` (as written in `file`) reaches through one of `imports`, if it is
279	/// imported.
280	fn imported_demand(file: &Utf8Path, imports: &[ImportBinding], reference: &str) -> Option<Demand> {
281	    let (head, rest) = match reference.split_once('.') {
282	        Some((head, rest)) => (head, Some(rest)),
283	        None => (reference, None),
284	    };
285	    let Some(binding) = imports.iter().find(|binding| binding.local_name == head) else {
286	        // `@types/react`'s UMD global (`export as namespace React`): `React.CSSProperties` without an import.
287	        let name = rest.filter(|_| head == "React")?;
288	        return Some(Demand { from: file.to_owned(), specifier: Box::from("react"), name: CompactString::from(name) });
289	    };
290	    let name = match (binding.exported_name.as_str(), rest) {
291	        ("*", Some(rest)) => CompactString::from(rest),
292	        ("*", None) => return None,
293	        (exported, Some(rest)) => CompactString::from(format!("{exported}.{rest}")),
294	        (exported, None) => CompactString::from(exported),
295	    };
296	    Some(Demand { from: file.to_owned(), specifier: Box::from(binding.specifier.as_str()), name })
297	}
298	
299	/// What project file `file` takes from packages (bare specifiers), sorted: each name it imports and uses in a type, and
300	/// each module it imports at all (a [`Demand`] with an empty name). TypeScript reads a module's React augmentations
301	/// whenever the program reaches the module, whether or not the file uses a name from it.
302	pub(crate) fn project_demands(file: &Utf8Path, data: &SourceData) -> Vec<Demand> {
303	    let mut refs = FxHashSet::default();
304	    referenced_names(data, &mut refs);
305	    let bare = |specifier: &str| !specifier.starts_with('.') && !specifier.starts_with('/');
306	    let mut demands: Vec<Demand> = refs
307	        .iter()
308	        .filter_map(|reference| imported_demand(file, &data.imports, reference))
309	        .filter(|demand| bare(&demand.specifier))
310	        .collect();
311	    demands.extend(data.imports.iter().filter(|binding| bare(&binding.specifier)).map(|binding| Demand {
312	        from: file.to_owned(),
313	        specifier: Box::from(binding.specifier.as_str()),
314	        name: CompactString::default(),
315	    }));
316	    // Every demand is from `file`, so the derived order's first key, a path of a hundred bytes, only ever ties.
317	    demands.sort_unstable_by(|a, b| (&a.specifier, &a.name).cmp(&(&b.specifier, &b.name)));
318	    demands.dedup();
319	    demands
320	}
321	
322	// ─── The layer ────────────────────────────────────────────────────────────────
323	
324	/// How many files, the module included, a search for React augmentations reads through one module's re-exports.
325	const AUGMENTATION_SCAN_FILES: usize = 64;
326	
327	/// How many layers a chain holds before the next extension flattens it into one.
328	///
329	/// An extension adds only the files it loaded, as a layer over the one it extends, so a growth costs what it loads and
330	/// not what the session already holds. Lookups walk the chain, so it is kept short: a flatten copies everything once
331	/// and the chain starts again.
332	const MAX_CHAIN_DEPTH: usize = 8;
333	
334	/// The sizes of a layer and its parents together, for [`DependencyLayer::resolves_like`] and `file_count`.
335	#[derive(Clone, Copy, Default)]
336	struct Totals {
337	    files: usize,
338	    react_files: usize,
339	    exports: usize,
340	    resolutions: usize,
341	    unresolved: usize,
342	}
343	
344	/// The dependency declarations a run loaded. Immutable once built; a watch revision or a lazy session that needs more
345	/// builds a new one over it, holding only what the extension added.
346	pub(crate) struct DependencyLayer {
347	    /// The layer this one extends. Everything below is this layer's own additions; the parent's are consulted through
348	    /// the accessors, `named_types` and `import_map`.
349	    parent: Option<Arc<DependencyLayer>>,
350	    /// Layers below this one.
351	    depth: usize,
352	    totals: Totals,
353	    /// Declaring files' component mappings: the value index. Nothing here is emitted.
354	    component_mappings: Vec<ComponentMapping>,
355	    /// Positions in `component_mappings` by component name, ascending: `ComponentProps<typeof X>` asks `component` for a
356	    /// name that is usually not here, and comparing every mapping's path to find that out dominated a design system's run.
357	    component_positions: FxHashMap<CompactString, Vec<usize>>,
358	    /// Falls back to the parent's.
359	    pub(crate) named_types: Arc<NamedTypeIndex>,
360	    /// Falls back to the parent's.
361	    pub(crate) import_map: Arc<ImportResolutionMap>,
362	    /// `(module, name)` → the declaring `(file, name)`, or `None` when the module's types do not export it.
363	    exports: dashmap::ReadOnlyView<(PathKey, CompactString), Option<(Utf8PathBuf, CompactString)>, FxBuildHasher>,
364	    /// `(directory, specifier)` → module, for every resolution the loader made.
365	    resolutions: FxHashMap<(Box<str>, Box<str>), Result<Utf8PathBuf, Unresolved>>,
366	    files: FxHashSet<PathKey>,
367	    /// React's files whose declarations' imports were followed; their imports are in `import_map`.
368	    react_files: FxHashSet<PathKey>,
369	    /// Each module a demand reached, with the files its re-exports lead to that augment React.
370	    augmenters: FxHashMap<PathKey, Vec<Utf8PathBuf>>,
371	    demands: FxHashSet<DemandKey>,
372	    unresolved: FxHashMap<DemandKey, Unresolved>,
373	    /// The `(file, name)` declarations whose references were followed.
374	    claimed: FxHashSet<(PathKey, CompactString)>,
375	    /// Every parsed file's data (stubs included), so an extension reuses them.
376	    parsed: FxHashMap<PathKey, Option<Arc<SourceData>>>,
377	    /// The panics this layer's own demands hit, contained, and the dependency files it could not read; the demands they
378	    /// covered stay unanswered.
379	    panics: Vec<Diagnostic>,
380	    /// The demands a file that could not be read left unfollowed, in this layer or, once flattened, the ones it took
381	    /// in; the next load over the layer follows them again.
382	    failed: FxHashSet<DemandKey>,
383	    /// A dependency file could not be read while this layer, or one it extends, was loaded ([`ReadFailed`]). The layer
384	    /// holds nothing derived from it, but what it holds is not the whole answer, so no load over it writes the index.
385	    degraded: bool,
386	}
387	
388	impl DependencyLayer {
389	    /// The contained panics of this layer and the ones it extends, in message order, and the files they could not read
390	    /// that no layer of the chain has read since: a session whose next load read the file answers as a fresh one.
391	    pub(crate) fn panic_diagnostics(&self) -> Vec<Diagnostic> {
392	        let unread =
393	            |diagnostic: &Diagnostic| diagnostic.file.as_deref().is_none_or(|file| self.parsed_data(file).is_none());
394	        let mut all: Vec<Diagnostic> =
395	            self.chain().flat_map(|layer| layer.panics.iter().filter(|d| unread(d)).cloned()).collect();
396	        all.sort_by(|a, b| a.message.cmp(&b.message));
397	        all
398	    }
399	
400	    /// This layer and then each one it extends.
401	    fn chain(&self) -> impl Iterator<Item = &DependencyLayer> {
402	        std::iter::successors(Some(self), |layer| layer.parent.as_deref())
403	    }
404	
405	    /// How many declaration files this layer holds, with its parents'.
406	    pub(crate) fn file_count(&self) -> usize {
407	        self.totals.files
408	    }
409	
410	    pub(crate) fn is_dependency_file(&self, file: &Utf8Path) -> bool {
411	        self.chain().any(|layer| layer.files.contains(file.as_str()))
412	    }
413	
414	    /// The declaring `(file, name)` of `name` exported from `module`, when the loader answered it.
415	    pub(crate) fn export_of(&self, module: &Utf8Path, name: &str) -> Option<&Option<(Utf8PathBuf, CompactString)>> {
416	        self.export_entry(&(PathKey::from(module), CompactString::from(name)))
417	    }
418	
419	    fn export_entry(&self, key: &(PathKey, CompactString)) -> Option<&Option<(Utf8PathBuf, CompactString)>> {
420	        self.chain().find_map(|layer| layer.exports.get(key))
421	    }
422	
423	    fn resolution(&self, key: &(Box<str>, Box<str>)) -> Option<&Result<Utf8PathBuf, Unresolved>> {
424	        self.chain().find_map(|layer| layer.resolutions.get(key))
425	    }
426	
427	    fn parsed_data(&self, file: &str) -> Option<&Option<Arc<SourceData>>> {
428	        self.chain().find_map(|layer| layer.parsed.get(file))
429	    }
430	
431	    fn augmenters_of(&self, module: &PathKey) -> Option<&Vec<Utf8PathBuf>> {
432	        self.chain().find_map(|layer| layer.augmenters.get(module))
433	    }
434	
435	    fn has_react_file(&self, file: &str) -> bool {
436	        self.chain().any(|layer| layer.react_files.contains(file))
437	    }
438	
439	    fn has_demand(&self, key: &DemandKey) -> bool {
440	        self.chain().any(|layer| layer.demands.contains(key))
441	    }
442	
443	    fn has_claimed(&self, key: &(PathKey, CompactString)) -> bool {
444	        self.chain().any(|layer| layer.claimed.contains(key))
445	    }
446	
447	    /// A dependency component by its declaring `(file, name)`.
448	    pub(crate) fn component(&self, file: &Utf8Path, name: &str) -> Option<&ComponentMapping> {
449	        self.chain().find_map(|layer| {
450	            layer
451	                .component_positions
452	                .get(name)?
453	                .iter()
454	                .filter_map(|&position| layer.component_mappings.get(position))
455	                .find(|mapping| mapping.file_path == file)
456	        })
457	    }
458	
459	    /// Why the loader found no declaration for `name` imported from `specifier` by a file in `dir`, if it didn't.
460	    pub(crate) fn unresolved_reason(&self, dir: &Utf8Path, specifier: &str, name: &str) -> Option<Unresolved> {
461	        let key = (Box::from(dir.as_str()), Box::from(specifier), CompactString::from(name));
462	        self.chain().find_map(|layer| layer.unresolved.get(&key)).copied()
463	    }
464	
465	    /// Whether `other`, a layer this one was extended from, resolves every name the way this one does: extending only
466	    /// adds, so equal counts mean nothing was added.
467	    pub(crate) fn resolves_like(&self, other: &DependencyLayer) -> bool {
468	        let (a, b) = (self.totals, other.totals);
469	        a.files == b.files
470	            && a.react_files == b.react_files
471	            && a.exports == b.exports
472	            && a.resolutions == b.resolutions
473	            && a.unresolved == b.unresolved
474	    }
475	
476	    /// Whether this layer has followed every one of `demands`.
477	    pub(crate) fn covers(&self, demands: &[Demand]) -> bool {
478	        demands.iter().all(|d| self.has_demand(&d.key()))
479	    }
480	
481	    /// The demands of `demands` this layer has not followed.
482	    pub(crate) fn missing(&self, demands: &[Demand]) -> Vec<Demand> {
483	        demands.iter().filter(|d| !self.has_demand(&d.key())).cloned().collect()
484	    }
485	
486	    /// Whether one of `demands` is unfollowed because a file it needed could not be read: a load over this layer may
487	    /// yet answer it, so what was resolved without it holds for one request only. A demand whose load panicked is not.
488	    pub(crate) fn awaits_read(&self, demands: &[Demand]) -> bool {
489	        demands
490	            .iter()
491	            .map(Demand::key)
492	            .any(|key| !self.has_demand(&key) && self.chain().any(|layer| layer.failed.contains(&key)))
493	    }
494	}
495	
496	// ─── Loading ──────────────────────────────────────────────────────────────────
497	
498	struct Loader<'a> {
499	    resolvers: &'a ModuleResolvers,
500	    project_dirs: &'a [Utf8PathBuf],
501	    /// The layer being extended, consulted before the maps below so an extension holds only its own additions.
502	    parent: Option<&'a DependencyLayer>,
503	    parsed: FxDashMap<PathKey, ParseCell>,
504	    resolutions: FxDashMap<(Box<str>, Box<str>), Result<Utf8PathBuf, Unresolved>>,
505	    exports: FxDashMap<(PathKey, CompactString), Option<(Utf8PathBuf, CompactString)>>,
506	    claimed: FxDashSet<(PathKey, CompactString)>,
507	    declaring: FxDashSet<PathKey>,
508	    react_files: FxDashSet<PathKey>,
509	    augmenters: FxDashMap<PathKey, Vec<Utf8PathBuf>>,
510	    /// For each module in `augmenters`, the stamps of the other packages its search read files from.
511	    augmenter_crossed: FxDashMap<PathKey, Vec<PackageStampRow>>,
512	    demands: FxDashSet<DemandKey>,
513	    /// The demands of `demands` that met a file that could not be read: not followed, as far as the layer says.
514	    failed: FxDashSet<DemandKey>,
515	    unresolved: FxDashMap<DemandKey, Unresolved>,
516	    /// Whether each directory `package_of` passed has a `package.json` file.
517	    package_manifests: FxDashMap<Box<str>, ProbeCell>,
518	    /// What `package_of` answered for each directory it was asked about, so a repeat is one lookup, not a walk.
519	    packages: FxDashMap<Box<str>, Option<Box<str>>>,
520	    /// Whether each directory `resolution_scope` passed has one of its marks.
521	    scope_marks: FxDashMap<Box<str>, ProbeCell>,
522	    /// What `resolution_scope` answered for each directory it was asked about.
523	    scopes: FxDashMap<Box<str>, Box<str>>,
524	    /// What each `(scope, specifier)` of a module-only demand resolved to, when outside the project and not React's.
525	    module_demands: FxDashMap<(Box<str>, Box<str>), ModuleCell>,
526	    /// What an augmentation search found in each file it passed through that was not parsed already.
527	    scans: FxDashMap<PathKey, ScanCell>,
528	    /// Something was resolved or answered that the index did not hold.
529	    learned: AtomicBool,
530	    /// The diagnostics of demands that panicked and of dependency files that could not be read.
531	    panics: Mutex<Vec<Diagnostic>>,
532	    /// A dependency file existed but could not be read ([`ReadFailed`]).
533	    read_failed: AtomicBool,
534	    /// How many times each file was read, and how long each read waits first, so a test can make readers meet.
535	    #[cfg(test)]
536	    reads: FxDashMap<PathKey, usize>,
537	    #[cfg(test)]
538	    read_pause: std::time::Duration,
539	}
