541	impl<'a> Loader<'a> {
542	    fn new(
543	        resolvers: &'a ModuleResolvers,
544	        project_dirs: &'a [Utf8PathBuf],
545	        parent: Option<&'a DependencyLayer>,
546	    ) -> Self {
547	        Loader {
548	            resolvers,
549	            project_dirs,
550	            parent,
551	            parsed: DashMap::default(),
552	            resolutions: DashMap::default(),
553	            exports: DashMap::default(),
554	            claimed: DashSet::default(),
555	            declaring: DashSet::default(),
556	            react_files: DashSet::default(),
557	            augmenters: DashMap::default(),
558	            augmenter_crossed: DashMap::default(),
559	            demands: DashSet::default(),
560	            failed: DashSet::default(),
561	            unresolved: DashMap::default(),
562	            package_manifests: DashMap::default(),
563	            packages: DashMap::default(),
564	            scope_marks: DashMap::default(),
565	            scopes: DashMap::default(),
566	            module_demands: DashMap::default(),
567	            scans: DashMap::default(),
568	            learned: AtomicBool::new(false),
569	            panics: Mutex::new(Vec::new()),
570	            read_failed: AtomicBool::new(false),
571	            #[cfg(test)]
572	            reads: DashMap::default(),
573	            #[cfg(test)]
574	            read_pause: std::time::Duration::ZERO,
575	        }
576	    }
577	}
578	
579	impl Loader<'_> {
580	    /// The text of a dependency file. One that is missing is skipped quietly (`Ok(None)`), since resolution found it a
581	    /// moment ago and a dangling link or a racing uninstall declares nothing. One that exists but cannot be read is
582	    /// [`ReadFailed`], reported once.
583	    fn read(&self, file: &Utf8Path) -> Result<Option<String>, ReadFailed> {
584	        #[cfg(test)]
585	        {
586	            *self.reads.entry(PathKey::from(file)).or_default() += 1;
587	            std::thread::sleep(self.read_pause);
588	        }
589	        match std::fs::read_to_string(file) {
590	            Ok(source) => Ok(Some(source)),
591	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
592	            Err(error) => {
593	                self.read_failed.store(true, Ordering::Relaxed);
594	                let mut diagnostic = Diagnostic::io_read_error(file, &error);
595	                // The package's types are not the project's, and the run still produces its output.
596	                diagnostic.severity = crate::types::DiagnosticSeverity::Warning;
597	                let mut failures = self.panics.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
598	                if !failures.iter().any(|known| known.file == diagnostic.file) {
599	                    failures.push(diagnostic);
600	                }
601	                Err(ReadFailed)
602	            }
603	        }
604	    }
605	
606	    /// The data of a dependency file, `None` when it is missing.
607	    fn parse(&self, file: &Utf8Path) -> Result<Option<Arc<SourceData>>, ReadFailed> {
608	        self.parse_source(file, None)
609	    }
610	
611	    /// `parse`, with the text of `file` when the caller has already read it. The file is read once per load: callers
612	    /// that ask at once wait for the first, and every caller gets its result, a failed read included, so one load sees
613	    /// one state of the file and opens it once. The layer keeps only files that were read (`load`), so the next load
614	    /// reads a failed one again.
615	    fn parse_source(&self, file: &Utf8Path, source: Option<String>) -> Result<Option<Arc<SourceData>>, ReadFailed> {
616	        if let Some(found) = self.parent.and_then(|parent| parent.parsed_data(file.as_str())) {
617	            return Ok(found.clone());
618	        }
619	        let cell = self.parsed.entry(PathKey::from(file)).or_default().clone();
620	        cell.get_or_init(|| {
621	            let source = match source {
622	                Some(source) => source,
623	                None => match self.read(file)? {
624	                    Some(source) => source,
625	                    None => return Ok(None),
626	                },
627	            };
628	            let mut data = crate::extractor::parse_file(file, &source);
629	            // Problems inside a package's types are not the project's; an unresolved demand is reported instead.
630	            data.diagnostics.clear();
631	            Ok(Some(Arc::new(data)))
632	        })
633	        .clone()
634	    }
635	
636	    /// Resolve `specifier` as imported by `from_file`, the way the resolver will.
637	    fn resolve(&self, from_file: &Utf8Path, specifier: &str) -> Result<Utf8PathBuf, Unresolved> {
638	        let dir = from_file.parent().map_or("", Utf8Path::as_str);
639	        let key = (Box::from(dir), Box::from(specifier));
640	        if let Some(found) = self.resolutions.get(&key) {
641	            return found.clone();
642	        }
643	        if let Some(found) = self.parent.and_then(|parent| parent.resolution(&key)) {
644	            return found.clone();
645	        }
646	        let result = match crate::resolver::resolve_module_with(
647	            &self.resolvers.main,
648	            &self.resolvers.types_first,
649	            specifier,
650	            from_file,
651	        ) {
652	            ModuleResolution::PackageTypes(path) => Ok(path),
653	            ModuleResolution::File(path) if is_typescript(&path) => Ok(path),
654	            ModuleResolution::File(_) => Err(Unresolved::NoTypes),
655	            ModuleResolution::Unresolved(_) => Err(Unresolved::Unresolvable),
656	        };
657	        // An unresolved import is not kept in the index, so asking again is not new knowledge.
658	        if result.is_ok() {
659	            self.learn(Utf8Path::new(dir));
660	        }
661	        self.resolutions.insert(key, result.clone());
662	        result
663	    }
664	
665	    fn in_project(&self, file: &Utf8Path) -> bool {
666	        !in_node_modules(file.as_str()) && self.project_dirs.iter().any(|dir| file.starts_with(dir))
667	    }
668	
669	    /// React's own types stay with the resolver's React handling (builtins, curated HTML attributes).
670	    fn is_react(file: &Utf8Path) -> bool {
671	        crate::origin::declaration_origin(file.as_str()) == crate::origin::Origin::React
672	    }
673	
674	    /// The `(file, name)` declaring `name` as exported from `module`.
675	    /// Incomplete when the walk passed a module it could not read: what it found then is the best this load has.
676	    fn find_export(&self, module: &Utf8Path, name: &str) -> Partial<Option<(Utf8PathBuf, CompactString)>> {
677	        let mut unkept = Unkept::default();
678	        let value = self.find_export_in(module, name, &mut FxHashSet::default(), &mut unkept);
679	        Partial { value, incomplete: unkept.unread }
680	    }
681	
682	    /// `find_export` within one walk. A lookup that met a module already on the walk (a re-export cycle) or passed one
683	    /// it could not read is returned but not kept, and `unkept` says why to every lookup that relied on it: a cycle's
684	    /// answer depends on where the walk entered it, and an unread module may have declared the name. Kept answers are
685	    /// therefore the same in any order, on any thread, and the same as a run that read every file. The walk goes on past
686	    /// a module it cannot read, as it does past one that does not export the name.
687	    fn find_export_in(
688	        &self,
689	        module: &Utf8Path,
690	        name: &str,
691	        visited: &mut FxHashSet<(PathKey, CompactString)>,
692	        unkept: &mut Unkept,
693	    ) -> Option<(Utf8PathBuf, CompactString)> {
694	        let key = (PathKey::from(module), CompactString::from(name));
695	        if let Some(found) = self.exports.get(&key) {
696	            return found.clone();
697	        }
698	        if let Some(found) = self.parent.and_then(|parent| parent.export_entry(&key)) {
699	            return found.clone();
700	        }
701	        if !visited.insert(key.clone()) {
702	            unkept.cycle = true;
703	            return None;
704	        }
705	        let mut own = Unkept::default();
706	        let found = self.find_export_uncached(module, name, visited, &mut own);
707	        visited.remove(&key);
708	        if !own.cycle && !own.unread {
709	            if let Some(dir) = module.parent() {
710	                self.learn(dir);
711	            }
712	            self.exports.insert(key, found.clone());
713	        }
714	        unkept.absorb(own);
715	        found
716	    }
