831	    fn follow<'s>(&'s self, scope: &rayon::Scope<'s>, demand: &Demand, key: &DemandKey) -> Partial<()> {
832	        if demand.name.is_empty() {
833	            return self.module_demand(scope, demand);
834	        }
835	        let module = match self.resolve(&demand.from, &demand.specifier) {
836	            Ok(module) => module,
837	            Err(reason) => {
838	                self.unresolved.insert(key.clone(), reason);
839	                return Partial::DONE;
840	            }
841	        };
842	        if self.in_project(&module) {
843	            return Partial::DONE;
844	        }
845	        if Self::is_react(&module) {
846	            // `@types/react` declares its exports inside `declare namespace React` (`export = React`).
847	            let qualified = CompactString::from(format!("React.{}", demand.name));
848	            return match self.parse(&module) {
849	                Ok(Some(data)) if declares(&data, &module, &qualified) => {
850	                    self.load_declaration(scope, module, qualified)
851	                }
852	                Ok(_) => Partial::DONE,
853	                Err(ReadFailed) => Partial::UNREAD,
854	            };
855	        }
856	        let found = self.find_export(&module, &demand.name);
857	        let loaded = match found.value {
858	            Some((file, name)) => self.load_declaration(scope, file, name),
859	            None if found.incomplete => Partial::DONE,
860	            None => {
861	                let cause = self.unresolved_cause(&module, &demand.name);
862	                if cause.incomplete {
863	                    return Partial::UNREAD;
864	                }
865	                self.unresolved.insert(key.clone(), cause.value.unwrap_or(Unresolved::NotExported));
866	                Partial::DONE
867	            }
868	        };
869	        loaded.and(Partial { value: (), incomplete: found.incomplete })
870	    }
