872	    /// Why a name `module` seems not to export was not found: a re-export hop on the way to it that cannot be
873	    /// resolved. A named or namespace hop for the name is the cause outright; an unresolvable `export *` only could
874	    /// have held it, so it is reported when nothing else explains the miss. `None` means every hop resolved;
875	    /// incomplete when a module on the way could not be read, which may have held the cause.
876	    fn unresolved_cause(&self, module: &Utf8Path, name: &str) -> Partial<Option<Unresolved>> {
877	        let mut visited = FxHashSet::default();
878	        let (mut star, mut unread) = (None, false);
879	        let cause = self.unresolved_cause_in(module, name, &mut visited, &mut star, &mut unread);
880	        Partial { value: cause.or(star), incomplete: unread }
881	    }
882	
883	    fn unresolved_cause_in(
884	        &self,
885	        module: &Utf8Path,
886	        name: &str,
887	        visited: &mut FxHashSet<(PathKey, CompactString)>,
888	        star: &mut Option<Unresolved>,
889	        unread: &mut bool,
890	    ) -> Option<Unresolved> {
891	        if !visited.insert((PathKey::from(module), CompactString::from(name))) {
892	            return None;
893	        }
894	        let data = match self.parse(module) {
895	            Ok(data) => data?,
896	            Err(ReadFailed) => {
897	                *unread = true;
898	                return None;
899	            }
900	        };
901	        let (head, rest) = match name.split_once('.') {
902	            Some((head, rest)) => (head, Some(rest)),
903	            None => (name, None),
904	        };
905	        // The order `find_export_uncached` reads them in: an explicit export answers for its name and shadows every
906	        // wildcard, so a wildcard is looked into only when no explicit export names it.
907	        for star_pass in [false, true] {
908	            for export in &data.exports {
909	                let (specifier, next) = match export {
910	                    LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. }
911	                        if !star_pass && local_name == head =>
912	                    {
913	                        let next = rest.map_or_else(|| source_name.clone(), |rest| format!("{source_name}.{rest}"));
914	                        (source_specifier, next)
915	                    }
916	                    LexedExport::ReExportNamespace { namespace, source_specifier }
917	                        if !star_pass && namespace == head =>
918	                    {
919	                        (source_specifier, rest?.to_owned())
920	                    }
921	                    // `export *` never carries `default`, as `find_export_uncached` enforces.
922	                    LexedExport::ReExportAll { source_specifier, .. } if star_pass && head != "default" => {
923	                        (source_specifier, name.to_owned())
924	                    }
925	                    _ => continue,
926	                };
927	                match self.resolve(module, specifier) {
928	                    Err(cause) if star_pass => {
929	                        star.get_or_insert(cause);
930	                    }
931	                    Err(cause) => return Some(cause),
932	                    Ok(target) => {
933	                        let cause = self.unresolved_cause_in(&target, &next, visited, star, unread);
934	                        if cause.is_some() || !star_pass {
935	                            return cause;
936	                        }
937	                    }
938	                }
939	            }
940	        }
941	        None
942	    }
