944	    /// A module imported for its own sake: only what it merges into React is read.
945	    ///
946	    /// Directories with the same resolution scope resolve a specifier to the same module, so the first of them to ask
947	    /// resolves it, finds and reads the files that augment React, and loads their declarations; the rest wait for the
948	    /// files and ask nothing. A file the search could not read leaves every demand of the scope incomplete alike, and
949	    /// the augmentations of the files it did read are loaded all the same.
950	    fn module_demand<'s>(&'s self, scope: &rayon::Scope<'s>, demand: &Demand) -> Partial<()> {
951	        let dir = demand.from.parent().map_or("", Utf8Path::as_str);
952	        let key = (self.resolution_scope(dir), demand.specifier.clone());
953	        let cell = self.module_demands.entry(key).or_default().clone();
954	        let mut first = false;
955	        let augmenting = cell.get_or_init(|| {
956	            first = true;
957	            let Ok(module) = self.resolve(&demand.from, &demand.specifier) else {
958	                return Partial::complete(Vec::new());
959	            };
960	            if self.in_project(&module) || Self::is_react(&module) {
961	                return Partial::complete(Vec::new());
962	            }
963	            let Partial { value: files, mut incomplete } = self.augmenting_files(&module);
964	            let mut parsed = Vec::new();
965	            for file in files {
966	                match self.parse(&file) {
967	                    Ok(Some(data)) => parsed.push((file, data)),
968	                    Ok(None) => {}
969	                    Err(ReadFailed) => incomplete = true,
970	                }
971	            }
972	            Partial { value: parsed, incomplete }
973	        });
974	        let loaded = if first { self.load_augmentations(scope, &augmenting.value) } else { Partial::DONE };
975	        loaded.and(Partial { value: (), incomplete: augmenting.incomplete })
976	    }
