978	    /// The nearest directory at or above `dir` where module resolution can start to differ: one with a `package.json`
979	    /// (its `imports`), a `tsconfig.json` or `jsconfig.json` (its `paths`) or a `node_modules`. A bare specifier
980	    /// resolves alike from every directory with the same scope. A directory with no such ancestor is its own.
981	    fn resolution_scope(&self, dir: &str) -> Box<str> {
982	        if let Some(found) = self.scopes.get(dir) {
983	            return found.clone();
984	        }
985	        let marks = ["package.json", "tsconfig.json", "jsconfig.json", "node_modules"];
986	        let has_mark = |candidate: &Utf8Path| marks.iter().any(|mark| candidate.join(mark).exists());
987	        let scope = Utf8Path::new(dir).ancestors().find(|candidate| probe_once(&self.scope_marks, candidate, has_mark));
988	        let scope = Box::<str>::from(scope.map_or(dir, Utf8Path::as_str));
989	        self.scopes.insert(Box::from(dir), scope.clone());
990	        scope
991	    }
