993	    /// The files `module` leads to through its re-exports that merge declarations into React
994	    /// (`declare module "react" { ... }`): TypeScript reads them whenever the program reaches the file, whether or not
995	    /// a name from them is used. The search is bounded ([`AUGMENTATION_SCAN_FILES`]), breadth first in source order,
996	    /// so the answer for a module is the same on any thread; it is kept, in the layer and in the index on disk, unless
997	    /// the search could not read a file: then it holds the files found among those read, for this load.
998	    fn augmenting_files(&self, module: &Utf8Path) -> Partial<Vec<Utf8PathBuf>> {
999	        let key = PathKey::from(module);
1000	        let known = self.augmenters.get(&key).map(|files| files.clone());
1001	        if let Some(files) = known.or_else(|| self.parent.and_then(|parent| parent.augmenters_of(&key)).cloned()) {
1002	            return Partial::complete(files);
1003	        }
1004	        let Partial { value: (files, crossed), incomplete } = self.find_augmenting_files(module);
1005	        if !incomplete {
1006	            self.augmenters.insert(key.clone(), files.clone());
1007	            self.augmenter_crossed.insert(key, crossed);
1008	            // An empty answer is persisted too, or the next run would scan the module's re-exports again.
1009	            module.parent().inspect(|dir| self.learn(dir));
1010	        }
1011	        Partial { value: files, incomplete }
1012	    }
