1014	    /// Loads the `React.`-qualified declarations of `augmenting`, the parsed files that augment React.
1015	    fn load_augmentations<'s>(
1016	        &'s self,
1017	        scope: &rayon::Scope<'s>,
1018	        augmenting: &[(Utf8PathBuf, Arc<SourceData>)],
1019	    ) -> Partial<()> {
1020	        let mut loaded = Partial::DONE;
1021	        for (file, data) in augmenting {
1022	            let mut names: Vec<&String> = data.interfaces.keys().collect();
1023	            names.sort();
1024	            for key in names {
1025	                if let Some(name) = key.strip_prefix(file.as_str()).and_then(|rest| rest.strip_prefix(':'))
1026	                    && name.starts_with("React.")
1027	                {
1028	                    loaded = loaded.and(self.load_declaration(scope, file.clone(), CompactString::from(name)));
1029	                }
1030	            }
1031	        }
1032	        loaded
1033	    }
