1035	    /// Whether `file` merges declarations into React, and the specifiers it re-exports, in order. A file that names
1036	    /// neither `React` nor the module `"react"` cannot declare into the React namespace, so one not already parsed is
1037	    /// only scanned for its re-exports and keeps nothing else: most files an augmentation search passes through
1038	    /// declare nothing the run needs. Read once per load, as `parse_source` reads; a file both scanned and parsed by
1039	    /// callers that meet may be read by each.
1040	    fn augmentation_scan(&self, file: &Utf8Path, entry: bool) -> Result<Option<Scan>, ReadFailed> {
1041	        let parsed = self.parent.and_then(|parent| parent.parsed_data(file.as_str())).cloned().map(Ok).or_else(|| {
1042	            let cell = self.parsed.get(file.as_str())?;
1043	            cell.get().cloned()
1044	        });
1045	        if let Some(parsed) = parsed {
1046	            return Ok(parsed?.map(|data| scan_of(&data, file)));
1047	        }
1048	        let cell = self.scans.entry(PathKey::from(file)).or_default().clone();
1049	        cell.get_or_init(|| {
1050	            let Some(source) = self.read(file)? else { return Ok(None) };
1051	            if entry || may_declare_into_react(&source) {
1052	                return Ok(self.parse_source(file, Some(source))?.map(|data| scan_of(&data, file)));
1053	            }
1054	            let re_exports = match may_re_export(&source) {
1055	                true => Arc::from(crate::extractor::re_export_specifiers(file, &source)),
1056	                false => Arc::from([]),
1057	            };
1058	            Ok(Some((false, re_exports)))
1059	        })
1060	        .clone()
1061	    }
