1063	    /// The files `module`'s re-exports lead to that augment React, and the stamps of the other packages the search read
1064	    /// files from: the answer holds only while those packages do not change, as well as the module's own.
1065	    /// Incomplete when it could not read a file on the way, which may have been one or led to one; the search goes on
1066	    /// with the rest.
1067	    fn find_augmenting_files(&self, module: &Utf8Path) -> Partial<(Vec<Utf8PathBuf>, Vec<PackageStampRow>)> {
1068	        let mut found = Vec::new();
1069	        let mut incomplete = false;
1070	        let mut seen: FxHashSet<Utf8PathBuf> = FxHashSet::default();
1071	        let mut queue = std::collections::VecDeque::from([module.to_owned()]);
1072	        while let Some(file) = queue.pop_front() {
1073	            if seen.len() >= AUGMENTATION_SCAN_FILES {
1074	                break;
1075	            }
1076	            if !seen.insert(file.clone()) || self.in_project(&file) || Self::is_react(&file) {
1077	                continue;
1078	            }
1079	            let (augments, re_exports) = match self.augmentation_scan(&file, file == module) {
1080	                Ok(Some(scan)) => scan,
1081	                Ok(None) => continue,
1082	                Err(ReadFailed) => {
1083	                    incomplete = true;
1084	                    continue;
1085	                }
1086	            };
1087	            if augments {
1088	                found.push(file.clone());
1089	            }
1090	            for specifier in re_exports.iter() {
1091	                if let Ok(target) = self.resolve(&file, specifier) {
1092	                    queue.push_back(target);
1093	                }
1094	            }
1095	        }
1096	        found.sort();
1097	        let own = module.parent().and_then(|dir| self.package_of(dir));
1098	        let mut crossed: Vec<PackageStampRow> = seen
1099	            .iter()
1100	            .filter_map(|file| self.package_of(file.parent()?))
1101	            .filter(|package| Some(package) != own.as_ref())
1102	            .collect::<FxHashSet<_>>()
1103	            .into_iter()
1104	            .filter_map(|package| {
1105	                let (mtime_ns, size) = package_stamp(&package)?;
1106	                Some((package.to_string(), mtime_ns, size))
1107	            })
1108	            .collect();
1109	        crossed.sort();
1110	        Partial { value: (found, crossed), incomplete }
1111	    }
