1113	    /// Mark `(file, name)` loaded and follow the names its declaration references: same-file ones in place, imported
1114	    /// ones as new demands. React's own declarations stay with the resolver's React handling (builtins, curated HTML
1115	    /// attributes), so React's files never enter the layer, but what they import does: `CSSProperties` extends
1116	    /// csstype's `Properties`. Incomplete, claiming nothing, when `file` could not be read (an export the index
1117	    /// answered, whose declaring file this load had not read); the demands it spawns answer for themselves.
1118	    fn load_declaration<'s>(&'s self, scope: &rayon::Scope<'s>, file: Utf8PathBuf, name: CompactString) -> Partial<()> {
1119	        if self.in_project(&file) {
1120	            return Partial::DONE;
1121	        }
1122	        let react = Self::is_react(&file);
1123	        let data = match self.parse(&file) {
1124	            Ok(Some(data)) => data,
1125	            Ok(None) => return Partial::DONE,
1126	            Err(ReadFailed) => return Partial::UNREAD,
1127	        };
1128	        // `Primitive.div` is a member of the value `Primitive`, whose declared type has it.
1129	        let mut stack: Vec<CompactString> =
1130	            name.split_once('.').map(|(head, _)| CompactString::from(head)).into_iter().collect();
1131	        stack.push(name);
1132	        while let Some(name) = stack.pop() {
1133	            let claim = (PathKey::from(file.as_path()), name.clone());
1134	            if self.parent.is_some_and(|parent| parent.has_claimed(&claim)) || !self.claimed.insert(claim) {
1135	                continue;
1136	            }
1137	            if react {
1138	                if !self.parent.is_some_and(|parent| parent.has_react_file(file.as_str())) {
1139	                    self.react_files.insert(PathKey::from(file.as_path()));
1140	                }
1141	            } else if !self.parent.is_some_and(|parent| parent.is_dependency_file(&file)) {
1142	                self.declaring.insert(PathKey::from(file.as_path()));
1143	            }
1144	            // The type a value is declared with (`declare const Primitive: Primitives`) goes with the value.
1145	            let value_type = CompactString::from(format!("typeof {name}"));
1146	            if declares(&data, &file, &value_type) {
1147	                stack.push(value_type);
1148	            }
1149	            let mut refs = FxHashSet::default();
1150	            declaration_refs(&data, &file, &name, &mut refs);
1151	            for reference in refs {
1152	                let qualified = react.then(|| CompactString::from(format!("React.{reference}")));
1153	                if declares(&data, &file, &reference) {
1154	                    stack.push(reference);
1155	                } else if declares(&data, &file, &format!("typeof {reference}")) {
1156	                    // `typeof NODES` names a value that has only its declared type.
1157	                    stack.push(CompactString::from(format!("typeof {reference}")));
1158	                } else if let Some(qualified) = qualified.filter(|q| declares(&data, &file, q)) {
1159	                    stack.push(qualified);
1160	                } else if let Some(demand) = imported_demand(&file, &data.imports, &reference) {
1161	                    self.spawn_demand(scope, demand);
1162	                }
1163	            }
1164	        }
1165	        Partial::DONE
1166	    }
