1168	    /// Note that an answer about `dir` is new. A project file's own imports are resolved on every run and never reach
1169	    /// the index, so they must not make a warm run rewrite it. Export answers of a package that `write_index` drops
1170	    /// still count here, since only the written bytes tell; `write_index` leaves the file alone when they are unchanged.
1171	    fn learn(&self, dir: &Utf8Path) {
1172	        if in_node_modules(dir.as_str()) && self.package_of(dir).is_some() {
1173	            self.learned.store(true, Ordering::Relaxed);
1174	        }
1175	    }
