1177	    /// The nearest directory at or above `dir` with a `package.json`, if it is inside `node_modules`.
1178	    fn package_of(&self, dir: &Utf8Path) -> Option<Box<str>> {
1179	        if let Some(found) = self.packages.get(dir.as_str()) {
1180	            return found.clone();
1181	        }
1182	        let has_manifest = |candidate: &Utf8Path| candidate.join("package.json").is_file();
1183	        let found = dir
1184	            .ancestors()
1185	            .find(|candidate| probe_once(&self.package_manifests, candidate, has_manifest))
1186	            .filter(|candidate| in_node_modules(candidate.as_str()))
1187	            .map(|candidate| Box::from(candidate.as_str()));
1188	        self.packages.insert(Box::from(dir.as_str()), found.clone());
1189	        found
1190	    }
1191	}
