1199	/// `probe(dir)`, asked of the disk once per load: the files of one tree share their ancestors, and a load's demands
1200	/// start together, so the threads that ask about one directory at once wait for one probe. A probe never waits on
1201	/// another directory's, and the callers walk the lexical ancestors in a loop, so a deep tree cannot deadlock or
1202	/// exhaust the stack.
1203	fn probe_once(memo: &FxDashMap<Box<str>, ProbeCell>, dir: &Utf8Path, probe: impl FnOnce(&Utf8Path) -> bool) -> bool {
1204	    #[cfg(test)]
1205	    CELL_LOOKUPS.with(|lookups| lookups.set(lookups.get() + 1));
1206	    let cell = match memo.get(dir.as_str()) {
1207	        Some(cell) => cell.clone(),
1208	        None => memo.entry(Box::from(dir.as_str())).or_default().clone(),
1209	    };
1210	    *cell.get_or_init(|| probe(dir))
1211	}
