1213	/// Whether `source` could declare into the React namespace: `declare module "react"` or `namespace React`, which are
1214	/// the only ways the extractor keys an interface as `React.`-qualified. A word that may be one of those, or follows a
1215	/// comment, counts; importing from "react" does not.
1216	fn may_declare_into_react(source: &str) -> bool {
1217	    ["React", "\"react\"", "'react'"].iter().any(|name| {
1218	        source.match_indices(name).any(|(at, _)| {
1219	            let before = source[..at].trim_end();
1220	            before.ends_with("module") || before.ends_with("namespace") || before.ends_with('/')
1221	        })
1222	    })
1223	}
