1225	/// Whether `source` could re-export anything: every spelling puts `{`, `*` or `default` after `export` (`export type {`
1226	/// too), and a comment there counts. A file that does not has nothing to parse for.
1227	fn may_re_export(source: &str) -> bool {
1228	    source.match_indices("export").any(|(at, word)| {
1229	        let rest = source[at + word.len()..].trim_start();
1230	        let rest = rest.strip_prefix("type").map_or(rest, str::trim_start);
1231	        rest.starts_with(['{', '*', '/']) || rest.starts_with("default")
1232	    })
1233	}
