1235	/// Whether `data`, the parse of `file`, declares into the React namespace, and the specifiers it re-exports, in order.
1236	fn scan_of(data: &SourceData, file: &Utf8Path) -> Scan {
1237	    let react_prefix = format!("{file}:React.");
1238	    let augments = data.interfaces.keys().any(|key| key.starts_with(&react_prefix));
1239	    let re_exports = data
1240	        .exports
1241	        .iter()
1242	        .filter_map(|export| match export {
1243	            LexedExport::ReExportNamed { source_specifier, .. }
1244	            | LexedExport::ReExportAll { source_specifier, .. }
1245	            | LexedExport::ReExportNamespace { source_specifier, .. } => Some(source_specifier.clone()),
1246	            LexedExport::LocalDeclaration { .. } => None,
1247	        })
1248	        .collect();
1249	    (augments, re_exports)
1250	}
