1252	/// Whether `file` declares `name` (an interface, type alias, enum, const array or component, possibly
1253	/// namespace-qualified).
1254	fn declares(data: &SourceData, file: &Utf8Path, name: &str) -> bool {
1255	    let key = format!("{file}:{name}");
1256	    data.interfaces.contains_key(&key)
1257	        || data.type_aliases.contains_key(&key)
1258	        || data.enums.contains_key(&key)
1259	        || data.const_arrays.contains_key(&key)
1260	        || data.component_mappings.iter().any(|m| m.binding_name() == name)
1261	        // A constant declared by its type alone (`declare const Primitive: Primitives`).
1262	        || data.type_aliases.contains_key(&format!("{file}:typeof {name}"))
1263	}
