18	/// Runs `work`, which may use rayon, on a thread and a pool of its own, and waits for it.
19	///
20	/// `grow` holds a lock while it loads dependencies, and the load fans out with `rayon::scope`. Called on a pool worker,
21	/// that wait steals other queued jobs, and a stolen request calls `grow` and blocks on the lock its own thread holds;
22	/// the other workers block on it too, so the scope's tasks have no worker left to run on. A plain thread blocks
23	/// without stealing, and its own pool keeps workers free for the load.
24	fn off_pool<R: Send>(work: impl FnOnce() -> R + Send) -> R {
25	    static POOL: std::sync::OnceLock<Option<rayon::ThreadPool>> = std::sync::OnceLock::new();
26	    let pool = POOL
27	        .get_or_init(|| {
28	            rayon::ThreadPoolBuilder::new().thread_name(|index| format!("caliper-deps-{index}")).build().ok()
29	        })
30	        .as_ref();
31	    let outcome = std::thread::scope(|scope| {
32	        scope
33	            .spawn(|| match pool {
34	                Some(pool) => pool.install(work),
35	                None => work(),
36	            })
37	            .join()
38	    });
39	    outcome.unwrap_or_else(|panic| std::panic::resume_unwind(panic))
40	}
