127	            ambient_global_files.to_vec(),
128	            named_types,
129	        )
130	        .with_dependencies(layer.clone())
131	        .with_react_types(react_types.clone());
132	        Engine { layer, ctx: Arc::new(ctx) }
133	    }
134	}
