136	/// How many times the layer grows for requests before the rest of the project's names load in the background. A
137	/// growth is cheap (it shares the project's indexes with the context it replaces), so a session that looks at a few
138	/// dozen components holds only the names they reach (shadcn: 181 declaration files after 50 requests, 450 once every
139	/// name is loaded, 30 MB more); one that reads across the project, as a static build does, reaches this and loads the
140	/// rest once instead of growing for every new component. Tests use a small project, so a small count.
141	const WHOLE_DEMAND_AFTER_GROWTHS: usize = 3;
142	
143	pub(super) struct Lazy {
144	    /// Each project file's dependency demands; files that demand nothing are absent.
145	    demands: FxHashMap<PathKey, Arc<[Demand]>>,
146	    /// Components by name, in output order, with their position in `GlobalSourceData::component_mappings`.
147	    by_name: FxHashMap<String, Vec<(ComponentId, usize)>>,
148	    memo: DashMap<ComponentId, Arc<Resolved>, FxBuildHasher>,
149	    engine: ArcSwap<Engine>,
150	    /// Serializes layer growth, so concurrent requests load a name once.
151	    growing: Mutex<()>,
152	    /// Whether the background load of every name the project takes from a package has started.
153	    whole_demand_started: std::sync::atomic::AtomicBool,
154	    /// The thread loading them, until [`Revision::wait_for_dependency_load`] joins it.
155	    whole_demand_thread: Mutex<Option<std::thread::JoinHandle<()>>>,
156	    /// How many times the layer grew (and the context was rebuilt or kept), for tests and stats.
157	    growths: std::sync::atomic::AtomicUsize,
158	}
159	
160	/// The components of `global` by name, each name's components in output order.
161	fn group_by_name(global: &GlobalSourceData, options: &PipelineOptions) -> FxHashMap<String, Vec<(ComponentId, usize)>> {
162	    let mut by_name: FxHashMap<String, Vec<(ComponentId, usize)>> = FxHashMap::default();
163	    for (id, index) in ordered_ids(global, options) {
164	        by_name.entry(id.name.clone()).or_default().push((id, index));
165	    }
166	    by_name
167	}
168	
169	fn demands_by_file(file_demands: Vec<(Utf8PathBuf, Vec<Demand>)>) -> FxHashMap<PathKey, Arc<[Demand]>> {
170	    file_demands
171	        .into_iter()
172	        .filter(|(_, demands)| !demands.is_empty())
173	        .map(|(file, demands)| (PathKey::from(file.as_path()), Arc::from(demands)))
174	        .collect()
175	}
