177	impl Revision {
178	    /// Discover, parse and merge every source file, and nothing more.
179	    pub(crate) fn cold_lazy(options: &PipelineOptions, id: u64) -> Revision {
180	        let Indexed {
181	            start,
182	            cache,
183	            src_files,
184	            global,
185	            head_diagnostics,
186	            file_diagnostics,
187	            mut lib_diagnostics,
188	            react_types,
189	            file_demands,
190	        } = Indexed::build(options);
191	        let global = Arc::new(global);
192	        let named_types = Arc::new(NamedTypeIndex::build(&global));
193	        let ambient_global_files = crate::resolver::compute_ambient_global_files(options);
194	        // The layer starts with the names the project takes from React. A batch run loads them for every component,
195	        // and loading them follows React's own imports (csstype), which any component's HTML attributes can reach
196	        // without its file naming them; a component's answer would otherwise depend on what was asked before it.
197	        // It also reads the persisted dependency index, so names a batch run already resolved cost no walk. The modules
198	        // the project imports start loaded as well: what they merge into React's interfaces reaches every component.
199	        let react: Vec<Demand> = file_demands
200	            .iter()
201	            .flat_map(|(_, demands)| {
202	                demands.iter().filter(|demand| &*demand.specifier == "react" || demand.name.is_empty()).cloned()
203	            })
204	            .collect();
205	        let layer = options.load_dependencies.then(|| Arc::new(dependency_types::load(react, options, None)));
206	        let engine = Engine::new(&global, options, &ambient_global_files, &named_types, layer, &react_types);
207	        lib_diagnostics.extend(engine.ctx.tsconfig_diagnostic.clone());
208	        let (dts_files_parsed, dts_cache_hits) = cache.counts();
209	        let tail_diagnostics: Vec<Diagnostic> = match Arc::try_unwrap(cache) {
210	            Ok(c) => c.save_to_disk(),
211	            Err(arc) => arc.save_to_disk(),
212	        }
213	        .into_iter()
214	        .collect();
215	        let lazy = Lazy {
216	            demands: demands_by_file(file_demands),
217	            by_name: group_by_name(&global, options),
218	            memo: DashMap::default(),
219	            engine: ArcSwap::from_pointee(engine),
220	            growing: Mutex::new(()),
221	            whole_demand_started: std::sync::atomic::AtomicBool::new(false),
222	            whole_demand_thread: Mutex::new(None),
223	            growths: std::sync::atomic::AtomicUsize::new(0),
224	        };
225	        Revision {
226	            id,
227	            global,
228	            named_types,
229	            dependencies: None,
230	            react_types,
231	            ambient_global_files,
232	            head_diagnostics,
233	            file_diagnostics,
234	            lib_diagnostics,
235	            tail_diagnostics,
236	            resolved: FxHashMap::default(),
237	            sites: Arc::default(),
238	            files: Arc::new(src_files.into_iter().collect()),
239	            dts_files_parsed,
240	            dts_cache_hits,
241	            duration_ms: start.elapsed().as_millis() as u64,
242	            output: Arc::new(empty_output()),
243	            keys: FxHashMap::default(),
244	            lazy: Some(lazy),
245	        }
246	    }
