252	    /// The component an eager revision published under `key`, as a lazy revision answers for it.
253	    pub(crate) fn published_component(&self, key: &str) -> Option<ComponentAnswer> {
254	        let entry = self.output.components.get(key)?.clone();
255	        let diagnostics = self
256	            .output
257	            .diagnostics
258	            .iter()
259	            .filter(|diagnostic| diagnostic.affects.iter().any(|affected| affected == key))
260	            .map(|diagnostic| Diagnostic { affects: vec![key.to_owned()], ..diagnostic.clone() })
261	            .collect();
262	        Some(ComponentAnswer { key: key.to_owned(), entry, diagnostics })
