265	    /// How many components this lazy revision indexed, how many it has resolved, and how many dependency declaration
266	    /// files it has loaded.
267	    pub(crate) fn lazy_counts(&self) -> Option<(usize, usize, usize)> {
268	        let lazy = self.lazy.as_ref()?;
269	        let loaded = lazy.engine.load().layer.as_ref().map_or(0, |layer| layer.file_count());
270	        Some((lazy.by_name.values().map(Vec::len).sum(), lazy.memo.len(), loaded))
