273	    /// The revision after `changed` was edited, created or deleted, and the keys whose answers may differ. The memo
274	    /// keeps every entry whose resolution did not read `changed`; the dependency layer carries over as it stands.
275	    pub(super) fn next_lazy(
276	        &self,
277	        options: &PipelineOptions,
278	        changed: &Utf8Path,
279	    ) -> Option<(Revision, IncrementalUpdate)> {
280	        let previous = self.lazy.as_ref()?;
281	        if !is_source_file(changed, &options.src_dirs, &options.exclude_patterns, self.source_files()) {
282	            return None;
283	        }
284	        let start = Instant::now();
285	        let Applied { global, named_types, file_diagnostics, files, change, demands, .. } =
286	            self.apply_change(options, changed, false);
287	        let global = Arc::new(global);
288	        let named_types = Arc::new(named_types);
289	
290	        let mut file_demands = previous.demands.clone();
291	        match demands.is_empty() {
292	            true => file_demands.remove(change.file.as_str()),
293	            false => file_demands.insert(PathKey::from(change.file), Arc::from(demands)),
294	        };
295	        let by_name = group_by_name(&global, options);
296	        let memo: DashMap<ComponentId, Arc<Resolved>, FxBuildHasher> = DashMap::default();
297	        let mut touched: FxHashSet<String> = FxHashSet::default();
298	        let mut affected_files: Vec<Utf8PathBuf> = Vec::new();
299	        for entry in previous.memo.iter() {
300	            let (id, resolved) = (entry.key(), entry.value());
301	            let kept = id.file != change.file
302	                && !resolved.affected_by(&change)
303	                && by_name.get(&id.name).is_some_and(|group| group.iter().any(|(candidate, _)| candidate == id));
304	            if kept {
305	                memo.insert(id.clone(), resolved.clone());
306	            } else {
307	                touched.insert(id.name.clone());
308	                affected_files.push(id.file.clone());
309	            }
310	        }
311	        // A name the changed file declared before or after keeps no memo, but its keys can still move.
312	        for groups in [&previous.by_name, &by_name] {
313	            for (name, group) in groups {
314	                if group.iter().any(|(id, _)| id.file == change.file) {
315	                    touched.insert(name.clone());
316	                }
317	            }
318	        }
319	        affected_files.sort();
320	        affected_files.dedup();
321	
322	        let layer = previous.engine.load().layer.clone();
323	        let engine = Engine::new(&global, options, &self.ambient_global_files, &named_types, layer, &self.react_types);
324	        // A kept answer is decided again against the new call sites, so an edit to a consumer can change its `used`
325	        // lists without touching its resolution. The new sites are the ones the next answer reads.
326	        if memo.iter().any(|entry| entry.value().evidence.is_some()) {
327	            let before = relevance_inputs::project_sites(&previous.engine.load().ctx);
328	            let after = relevance_inputs::project_sites(&engine.ctx);
329	            for entry in memo.iter().filter(|entry| entry.value().redecided(&before, &after)) {
330	                touched.insert(entry.key().name.clone());
331	            }
332	        }
333	        let next = Revision {
334	            id: self.id + 1,
335	            global,
336	            named_types,
337	            dependencies: None,
338	            react_types: self.react_types.clone(),
339	            ambient_global_files: self.ambient_global_files.clone(),
340	            head_diagnostics: self.head_diagnostics.clone(),
341	            file_diagnostics,
342	            lib_diagnostics: self.lib_diagnostics.clone(),
343	            tail_diagnostics: self.tail_diagnostics.clone(),
344	            resolved: FxHashMap::default(),
345	            sites: Arc::default(),
346	            files: Arc::new(files),
347	            dts_files_parsed: self.dts_files_parsed,
348	            dts_cache_hits: self.dts_cache_hits,
349	            duration_ms: self.duration_ms,
350	            output: Arc::new(empty_output()),
351	            keys: FxHashMap::default(),
352	            lazy: Some(Lazy {
353	                demands: file_demands,
354	                by_name,
355	                memo,
356	                engine: ArcSwap::from_pointee(engine),
357	                growing: Mutex::new(()),
358	                whole_demand_started: std::sync::atomic::AtomicBool::new(false),
359	                whole_demand_thread: Mutex::new(None),
360	                growths: std::sync::atomic::AtomicUsize::new(0),
361	            }),
362	        };
363	        let update = self.lazy_delta(&next, options, &touched, affected_files, start);
364	        Some((next, update))
365	    }
366	
367	    /// The revision after a change that can alter how every import resolves, rebuilt from scratch. Every name the
368	    /// previous revision had resolved is reported, since any answer may differ.
369	    pub(super) fn rebuilt_lazy(&self, options: &PipelineOptions) -> Option<(Revision, IncrementalUpdate)> {
370	        let previous = self.lazy.as_ref()?;
371	        let start = Instant::now();
372	        let next = Revision::cold_lazy(options, self.id + 1);
373	        let touched: FxHashSet<String> = previous.memo.iter().map(|entry| entry.key().name.clone()).collect();
374	        let mut affected_files: Vec<Utf8PathBuf> = previous.memo.iter().map(|entry| entry.key().file.clone()).collect();
375	        affected_files.sort();
376	        affected_files.dedup();
377	        let update = self.lazy_delta(&next, options, &touched, affected_files, start);
378	        Some((next, update))
379	    }
380	
381	    /// The delta from this lazy revision to `next`: the keys of every `touched` name there, and the keys it had that
382	    /// `next` does not. Answers are not part of it; a consumer asks again.
383	    fn lazy_delta(
384	        &self,
385	        next: &Revision,
386	        options: &PipelineOptions,
387	        touched: &FxHashSet<String>,
388	        affected_files: Vec<Utf8PathBuf>,
389	        start: Instant,
390	    ) -> IncrementalUpdate {
391	        let mut updated_keys: Vec<String> = Vec::new();
392	        let mut removed_keys: Vec<String> = Vec::new();
393	        for name in touched {
394	            let now = next.group_keys(options, name, true);
395	            removed_keys.extend(self.group_keys(options, name, true).into_iter().filter(|key| !now.contains(key)));
396	            updated_keys.extend(now);
397	        }
398	        updated_keys.sort();
399	        updated_keys.dedup();
400	        removed_keys.sort();
401	        removed_keys.dedup();
402	        IncrementalUpdate {
403	            revision: next.id,
404	            updated_components: Vec::new(),
405	            updated_keys,
406	            removed_keys,
407	            affected_files,
408	            diagnostics: Vec::new(),
409	            removed_diagnostics: Vec::new(),
410	            duration_ms: start.elapsed().as_millis() as u64,
411	        }
412	    }
413	
414	    /// `component` resolved, memoized. `None` when the position is not one of this revision's mappings.
415	    fn lazy_resolved(&self, options: &PipelineOptions, id: &ComponentId, index: usize) -> Option<Arc<Resolved>> {
416	        let lazy = self.lazy.as_ref()?;
417	        if let Some(hit) = lazy.memo.get(id) {
418	            return Some(hit.clone());
419	        }
420	        let mapping = self.global.component_mappings.get(index)?;
421	        // The component's own file almost always reaches its own names; loading them first saves a resolution.
422	        if let Some(seed) = lazy.demands.get(mapping.file_path.as_str()) {
423	            self.grow(options, lazy, seed);
424	        }
425	        let mut asked_for: Vec<dependency_types::Demand> = Vec::new();
426	        loop {
427	            let engine = lazy.engine.load_full();
428	            let (entry, diagnostics, depends_on, evidence, attributes) =
429	                resolve_guarded(&[mapping], &engine.ctx).into_iter().next()?;
430	            let missing = match &engine.layer {
431	                Some(layer) => {
432	                    let mut missing = Vec::new();
433	                    for file in &depends_on.files {
434	                        if let Some(demands) = lazy.demands.get(file) {
435	                            missing.extend(layer.missing(demands));
436	                        }
437	                    }
438	                    missing
439	                }
440	                None => Vec::new(),
441	            };
442	            // A resolution against a layer that lacked a name it reached is discarded, and so is its context's memo.
443	            // A load that left the same names missing answered none of them (a demand whose load panicked stays
444	            // unanswered), so asking again would never end.
445	            if missing.is_empty() || missing == asked_for {
446	                let resolved = Arc::new(Resolved { entry, diagnostics, depends_on, evidence, attributes });
447	                // A name a file that could not be read left missing may load on the next request, whichever component
448	                // asks: the answer without it is this request's alone.
449	                if engine.layer.as_ref().is_some_and(|layer| layer.awaits_read(&missing)) {
450	                    return Some(resolved);
451	                }
452	                return Some(lazy.memo.entry(id.clone()).or_insert(resolved).clone());
453	            }
454	            self.grow(options, lazy, &missing);
455	            asked_for = missing;
456	        }
457	    }
458	
459	    /// Once the layer has grown [`WHOLE_DEMAND_AFTER_GROWTHS`] times, load every name the project's files take from a
460	    /// package on a thread of its own, once.
461	    ///
462	    /// Each growth of the layer rebuilds the resolution context, so a session that grows one request at a time pays
463	    /// that rebuild for every new component (Spectrum: 33 rebuilds, about 140 of the 300 ms a project read end to end
464	    /// took). A session that asks about a few components never gets here, and holds only the names they reach; one
465	    /// that reads across the project does, and the later requests find every name loaded. A request that needs a name
466	    /// before the thread has loaded it waits for the same lock and loads it, as it would have anyway.
467	    pub(crate) fn load_whole_demand_in_background(self: &Arc<Self>, options: &PipelineOptions) {
468	        use std::sync::atomic::Ordering::Relaxed;
469	        let Some(lazy) = &self.lazy else { return };
470	        if !options.load_dependencies
471	            || lazy.growths.load(Relaxed) < WHOLE_DEMAND_AFTER_GROWTHS
472	            || lazy.whole_demand_started.swap(true, Relaxed)
473	        {
474	            return;
475	        }
476	        let (revision, options) = (self.clone(), options.clone());
477	        let spawned = std::thread::Builder::new().name("caliper-whole-demand".into()).spawn(move || {
478	            drop(crate::panic_guard::contain_panic("load_whole_demand", || {
479	                let Some(lazy) = &revision.lazy else { return };
480	                let all: Vec<Demand> = lazy.demands.values().flat_map(|demands| demands.iter().cloned()).collect();
481	                revision.grow(&options, lazy, &all);
482	            }));
483	        });
484	        // A thread that cannot start costs the speed-up, never an answer.
485	        if let Ok(handle) = spawned {
486	            *lazy.whole_demand_thread.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(handle);
487	        }
488	    }
489	
490	    /// Wait until the background load [`Self::load_whole_demand_in_background`] started has finished. Without one,
491	    /// returns at once.
492	    pub(crate) fn wait_for_dependency_load(&self) {
493	        let Some(lazy) = &self.lazy else { return };
494	        let handle = lazy.whole_demand_thread.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take();
495	        if let Some(handle) = handle {
496	            drop(handle.join());
497	        }
498	    }
499	
500	    /// Whether the session's current context holds this revision's own project index, not a copy of it: growing the
501	    /// layer must not clone the project's declarations.
502	    #[cfg(test)]
503	    pub(crate) fn context_shares_project_index(&self) -> Option<bool> {
504	        let lazy = self.lazy.as_ref()?;
505	        Some(lazy.engine.load().ctx.named_types.shares_declarations_with(&self.named_types))
506	    }
507	
508	    /// How many times the dependency layer grew since this revision was built.
509	    #[cfg(test)]
510	    pub(crate) fn layer_growths(&self) -> usize {
511	        self.lazy.as_ref().map_or(0, |lazy| lazy.growths.load(std::sync::atomic::Ordering::Relaxed))
512	    }
513	
514	    /// Load `demands` into the dependency layer unless a concurrent request already did.
515	    fn grow(&self, options: &PipelineOptions, lazy: &Lazy, demands: &[Demand]) {
516	        let _growing = lazy.growing.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
517	        let engine = lazy.engine.load_full();
518	        let Some(layer) = &engine.layer else { return };
519	        let missing = layer.missing(demands);
520	        if missing.is_empty() {
521	            return;
522	        }
523	        let extended = Arc::new(off_pool(|| dependency_types::load(missing, options, Some(layer))));
524	        lazy.growths.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
525	        // Names that were already loaded, or that no package declares, add nothing the resolver reads, so the
526	        // context and its memos stay; only the record of what was asked for moves on.
527	        if extended.resolves_like(layer) {
528	            lazy.engine.store(Arc::new(Engine { layer: Some(extended), ctx: engine.ctx.clone() }));
529	            return;
530	        }
531	        // The new context shares the project's index, import map, resolvers and bare-name tables with the old one;
532	        // rebuilding them for every growth was most of what a session reading across a project spent.
533	        let named_types = Arc::new(self.named_types.with_fallback(extended.named_types.clone()));
534	        let ctx = Arc::new(engine.ctx.over_layer(named_types, Some(extended.clone())));
535	        let next = Engine { layer: Some(extended), ctx };
536	        // A memo that reached a project file whose names the old layer lacked was computed without them, and stays
537	        // behind; the rest hold for the larger layer, so the next component does not rebuild them.
538	        let covered = |file: &str| lazy.demands.get(file).is_none_or(|demands| layer.covers(demands));
539	        next.ctx.inherit_memos(&engine.ctx, |deps, read_in| {
540	            covered(read_in) && deps.files.iter().all(|file| covered(std::borrow::Borrow::<str>::borrow(file)))
541	        });
542	        lazy.engine.store(Arc::new(next));
543	    }
544	
545	    /// The keys a batch run publishes the components named `name` under, with each key's position in the group.
546	    /// Only an imported-member alias can be left out (when its package isn't loaded it has nothing to show), so only
547	    /// those are resolved to decide. With `listing`, a session that loads dependencies assumes they are all published
548	    /// instead: deciding would load the package of every alias in the project.
549	    fn group_positions(&self, options: &PipelineOptions, name: &str, listing: bool) -> Vec<(String, usize)> {
550	        let Some(group) = self.lazy.as_ref().and_then(|lazy| lazy.by_name.get(name)) else { return Vec::new() };
551	        let mut keyed: Vec<(String, usize)> = Vec::with_capacity(group.len());
552	        let mut published = 0;
553	        for (position, (id, index)) in group.iter().enumerate() {
554	            let Some(mapping) = self.global.component_mappings.get(*index) else { continue };
555	            let assumed = listing && options.load_dependencies;
556	            if matches!(mapping.rule, DetectionRule::ImportedMemberAlias | DetectionRule::FactoryResult) && !assumed {
557	                let empty = self
558	                    .lazy_resolved(options, id, *index)
559	                    .is_some_and(|resolved| resolved.entry.props.is_empty() && resolved.entry.inheritance.is_empty());
560	                if empty {
561	                    continue;
562	                }
563	            }
564	            published += 1;
565	            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
566	            let key = if published == 1 { name.to_owned() } else { format!("{name} ({})", mapping.file_path) };
567	            // Two components with one key: the later one is kept, as in the output map.
568	            match keyed.iter_mut().find(|(existing, _)| *existing == key) {
569	                Some(slot) => slot.1 = position,
570	                None => keyed.push((key, position)),
571	            }
572	        }
573	        keyed
574	    }
575	
576	    fn group_keys(&self, options: &PipelineOptions, name: &str, listing: bool) -> Vec<String> {
577	        self.group_positions(options, name, listing).into_iter().map(|(key, _)| key).collect()
578	    }
579	
580	    /// Every key a batch run would publish, sorted. Without `load_dependencies` it resolves the imported-member
581	    /// aliases to decide which are published; with it, it lists them all and never loads a dependency, so the list
582	    /// can include an alias whose package has nothing to show, which `lazy_component` then answers `None` for.
583	    pub(crate) fn lazy_keys(&self, options: &PipelineOptions) -> Vec<String> {
584	        let Some(lazy) = &self.lazy else { return Vec::new() };
585	        let mut keys: Vec<String> = lazy.by_name.keys().flat_map(|name| self.group_keys(options, name, true)).collect();
586	        keys.sort();
587	        keys
588	    }
589	
590	    /// Where each key [`Self::lazy_keys`] lists is declared, sorted by key. Parsing alone answers it; nothing is
591	    /// resolved.
592	    pub(crate) fn lazy_index(&self, options: &PipelineOptions) -> Vec<ComponentLocation> {
593	        let Some(lazy) = &self.lazy else { return Vec::new() };
594	        let mut index: Vec<ComponentLocation> = lazy
595	            .by_name
596	            .iter()
597	            .flat_map(|(name, group)| {
598	                self.group_positions(options, name, true).into_iter().filter_map(|(key, position)| {
599	                    let (id, index) = group.get(position)?;
600	                    let exports = self.global.component_mappings.get(*index)?.exports.clone();
601	                    Some(ComponentLocation { key, file_path: id.file.clone(), display_name: id.name.clone(), exports })
602	                })
603	            })
604	            .collect();
605	        index.sort_by(|a, b| a.key.cmp(&b.key));
606	        index
607	    }
608	
609	    /// [`Self::lazy_component`] for each of `keys`. The dependency names of every requested component's own file are
610	    /// loaded once up front and the first component is resolved alone, which warms the memos the rest share; resolving
611	    /// them all at once instead makes every thread rebuild the same chains and restart on each layer growth.
612	    pub(crate) fn lazy_components(&self, options: &PipelineOptions, keys: &[String]) -> Vec<Option<ComponentAnswer>> {
613	        use rayon::prelude::*;
614	        let Some(lazy) = &self.lazy else { return vec![None; keys.len()] };
615	        let mut seed: Vec<Demand> = Vec::new();
616	        let mut seeded: FxHashSet<&Utf8Path> = FxHashSet::default();
617	        for key in keys {
618	            let Some((id, index)) = self.lazy_target(options, key) else { continue };
619	            let Some(mapping) = self.global.component_mappings.get(index) else { continue };
620	            if let Some(demands) = lazy.demands.get(mapping.file_path.as_str()).filter(|_| seeded.insert(&id.file)) {
621	                seed.extend(demands.iter().cloned());
622	            }
623	        }
624	        if !seed.is_empty() {
625	            self.grow(options, lazy, &seed);
626	        }
627	        let mut answers: Vec<Option<ComponentAnswer>> = vec![None; keys.len()];
628	        let Some((first, rest)) = keys.split_first() else { return answers };
629	        let (head, tail) = answers.split_at_mut(1);
630	        if let Some(slot) = head.first_mut() {
631	            *slot = self.lazy_component(options, first);
632	        }
633	        tail.par_iter_mut().zip(rest.par_iter()).for_each(|(slot, key)| *slot = self.lazy_component(options, key));
634	        answers
635	    }
636	
637	    /// The key a batch run publishes the component `name` declared in `file` under. `None` when `file` declares no
638	    /// such component, or a batch run would leave it out.
639	    pub(crate) fn lazy_key_in(&self, options: &PipelineOptions, file: &Utf8Path, name: &str) -> Option<String> {
640	        let group = self.lazy.as_ref()?.by_name.get(name)?;
641	        self.group_positions(options, name, false)
642	            .into_iter()
643	            .rev()
644	            .find(|(_, position)| group.get(*position).is_some_and(|(id, _)| id.file == file))
645	            .map(|(key, _)| key)
646	    }
647	
648	    /// The component a batch run publishes under `key`, and its place in the revision: the id and the position of
649	    /// its mapping. `None` for a key with no component.
650	    fn lazy_target(&self, options: &PipelineOptions, key: &str) -> Option<(&ComponentId, usize)> {
651	        let lazy = self.lazy.as_ref()?;
652	        // `key` is a bare name, or `Name (file)`; a name may itself contain " (" only in a path, never a component.
653	        let names = std::iter::once(key).chain(key.match_indices(" (").map(|(at, _)| &key[..at]));
654	        let (name, position) = names.into_iter().find_map(|name| {
655	            let position =
656	                self.group_positions(options, name, false).into_iter().find(|(candidate, _)| candidate == key)?.1;
657	            Some((name, position))
658	        })?;
659	        let (id, index) = lazy.by_name.get(name)?.get(position)?;
660	        Some((id, *index))
661	    }
662	
663	    /// The component a batch run publishes under `key`, resolved now (or answered from the memo), with its
664	    /// diagnostics. `None` for a key the project has no component under.
665	    pub(crate) fn lazy_component(&self, options: &PipelineOptions, key: &str) -> Option<ComponentAnswer> {
666	        let (id, index) = self.lazy_target(options, key)?;
667	        let resolved = self.lazy_resolved(options, id, index)?;
668	        // A lazy revision counts call sites with its context, on the first answer that needs them.
669	        let sites = self.lazy.as_ref().map(|lazy| relevance_inputs::project_sites(&lazy.engine.load_full().ctx));
670	        let entry = resolved.answer(&sites.unwrap_or_default());
671	        let mut diagnostics = DiagnosticSet::default();
672	        diagnostics.extend(resolved.diagnostics.own.iter().cloned(), Some(key));
673	        for chunk in &resolved.diagnostics.shared {
674	            diagnostics.extend_shared(chunk, key);
675	        }
676	        // A panic in the dependency loader may have left any component's types unexpanded, so every answer carries it.
677	        if let Some(layer) = self.lazy.as_ref().and_then(|lazy| lazy.engine.load_full().layer.clone()) {
678	            diagnostics.extend(layer.panic_diagnostics(), None);
679	        }
680	        Some(ComponentAnswer { key: key.to_owned(), entry, diagnostics: diagnostics.finish() })
681	    }
682	}
