1	//! Generic components, read through an instantiation the checker forms itself.
2	//!
3	//! The props parameter of `function Poly<E extends ElementType = "div">(props: PolyProps<E>)` is `PolyProps<E>` with `E`
4	//! open, which has two props where `<Poly />` has every attribute of a `div`. The checker's API has no request that
5	//! instantiates a signature, so the instantiation is written as source: one file, held in the checker's memory and never
6	//! on disk (`updateSnapshot` with a `fileSystem` layer), declares for each such component
7	//!
8	//! ```ts
9	//! import type { "Poly" as CaliperComponent0 } from "/project/src/Poly.tsx"; export type CaliperProbe0 = Parameters<typeof CaliperComponent0<"div">>[0];
10	//! ```
11	//!
12	//! and the props are those of `CaliperProbe0`, read as any props type is. The file is added to a snapshot derived from the
13	//! one that answered the other components, its program rooted at the probe file too, made only when a requested
14	//! component is generic, so a project without one sends no request more. A line the checker reports an error on (a
15	//! default it prints with a name the file cannot see) sends that component to its structural result with the error as
16	//! the reason, and a checker that does not load the file sends them all; a result is never read from an instantiation
17	//! that did not form.
18	//!
19	//! A printed default is text, and the probe file is another module than the component's: a name it prints may resolve
20	//! there to another symbol than it does in the component's module (the module's own `FormData` against the global
21	//! one), which forms without an error. So the line also declares each type argument as a type of its own and the
22	//! signature as `CaliperSignature0`, and a component is read only when each argument is, in the checker that holds the
23	//! probe file, the very type its signature declares as the default ([`arguments_keep_their_meaning`]). That is the one
24	//! place the pattern "the probe's type arguments resolve, in the probe file, to what they resolve to in the component's
25	//! module" is enforced; a default that does not pass sends the component to its structural result.
26	
27	use std::sync::Arc;
28	
29	use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticOutcome};
30	use camino::Utf8Path;
31	use rustc_hash::FxHashMap;
32	
33	use crate::component;
34	use crate::convert::Converter;
35	use crate::rpc::{CallError, FileDiagnostic, Rpc, SignatureInfo, SignatureKind, SymbolRef};
36	use crate::{Target, fallback_of};
37	
38	/// The file the instantiations are declared in, in the project's root directory. It exists only in the checker's memory.
39	const PROBE_FILE: &str = "__caliper_instantiations__.ts";
40	
41	/// A generic component to read through an instantiation: the name its module exports it under, and the type arguments.
42	#[derive(Debug, Clone)]
43	pub(crate) struct Instantiation {
44	    pub export: String,
45	    pub arguments: Vec<String>,
46	}
47	
48	/// The type arguments of the instantiation a generic component gets when written without any (`<Poly />`): its first
49	/// type parameter's declared default, as the checker prints it. The checker fills in the parameters after it from their
50	/// own defaults, which may refer to the first. `None` when the component is not generic or its first type parameter
51	/// declares no default: then no instantiation is the one a story renders, and the props keep the open parameters.
52	pub(crate) async fn default_arguments(rpc: &Rpc, signature: &SignatureInfo) -> Result<Option<Vec<String>>, CallError> {
53	    if signature.type_parameters.is_empty() {
54	        return Ok(None);
55	    }
56	    // The ids a signature lists are not handles the checker knows until it has answered for them itself.
57	    let parameters = rpc.type_parameters(signature.id).await?;
58	    let Some(first) = parameters.first() else { return Ok(None) };
59	    let Some(default) = rpc.default_of_type_parameter(first.id).await? else { return Ok(None) };
60	    Ok(Some(vec![rpc.type_to_string(default.id).await?]))
61	}
62	
63	/// Whether each type argument the probe file declares for component `index` is the type its signature declares as the
64	/// default of that parameter, in the checker that holds the probe file: the same type, not one of the same name.
65	async fn arguments_keep_their_meaning(
66	    layered: &Rpc,
67	    probes: &FxHashMap<String, SymbolRef>,
68	    index: usize,
69	    instantiation: &Instantiation,
70	) -> Result<bool, CallError> {
71	    let Some(signature_alias) = probes.get(&format!("CaliperSignature{index}")) else { return Ok(false) };
72	    let component = layered.declared_type_of_symbol(signature_alias).await?;
73	    let signatures = layered.signatures(component.id, SignatureKind::Call).await?;
74	    let [signature] = signatures.as_slice() else { return Ok(false) };
75	    let parameters = layered.type_parameters(signature.id).await?;
76	    for (position, parameter) in parameters.iter().enumerate().take(instantiation.arguments.len()) {
77	        let Some(default) = layered.default_of_type_parameter(parameter.id).await? else { return Ok(false) };
78	        let Some(argument_alias) = probes.get(&format!("CaliperArgument{index}_{position}")) else {
79	            return Ok(false);
80	        };
81	        if layered.declared_type_of_symbol(argument_alias).await?.id != default.id {
82	            return Ok(false);
83	        }
84	    }
85	    Ok(true)
86	}
87	
88	/// The line of the probe file that instantiates `instantiation`, the component exported by `file`: the instantiation's
89	/// props, the component's signature and each type argument, which [`arguments_keep_their_meaning`] compares. Each
90	/// component is one line, so an error the checker reports is the error of the line it starts on.
91	fn probe_line(index: usize, file: &Utf8Path, instantiation: &Instantiation) -> String {
92	    let quoted = |text: &str| serde_json::Value::String(text.to_string()).to_string();
93	    let declared: String = instantiation
94	        .arguments
95	        .iter()
96	        .enumerate()
97	        .map(|(position, argument)| format!(" export type CaliperArgument{index}_{position} = {argument};"))
98	        .collect();
99	    format!(
100	        "import type {{ {export} as CaliperComponent{index} }} from {file}; export type CaliperProbe{index} = \
101	         Parameters<typeof CaliperComponent{index}<{arguments}>>[0]; export type CaliperSignature{index} = typeof \
102	         CaliperComponent{index};{declared}",
103	        export = quoted(&instantiation.export),
104	        file = quoted(file.as_str()),
105	        arguments = instantiation.arguments.join(", "),
106	    )
107	}
108	
109	/// The written form of an instantiation, for a reason: `Poly<"div">`.
110	fn written(target: &Target, instantiation: &Instantiation) -> String {
111	    format!("{}<{}>", target.display_name, instantiation.arguments.join(", "))
112	}
113	
114	/// Answers each generic component from its instantiation, in a snapshot derived from `rpc`'s whose program is
115	/// rooted at `root_files` and the probe file ([`Rpc::layered`]). The snapshot is released before this returns.
116	pub(crate) async fn answer(
117	    rpc: &Rpc,
118	    root_files: &[String],
119	    project_root: &Utf8Path,
120	    interner: &PropInterner,
121	    reverse: bool,
122	    mut pending: Vec<(Target, Instantiation)>,
123	) -> Result<SemanticOutcome, CallError> {
124	    let mut outcome = SemanticOutcome::default();
125	    // The file's text is part of the request, so it must not depend on the order the components were answered in.
126	    pending.sort_by(|(a, _), (b, _)| {
127	        (&a.file_path, &a.display_name, &a.key).cmp(&(&b.file_path, &b.display_name, &b.key))
128	    });
129	    let probe = project_root.join(PROBE_FILE);
130	    let text: Vec<String> = pending
131	        .iter()
132	        .enumerate()
133	        .map(|(index, (target, instantiation))| probe_line(index, &target.file_path, instantiation))
134	        .collect();
135	    let all_fall_back = |outcome: &mut SemanticOutcome, reason: &str| {
136	        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
137	    };
138	
139	    let layered = match rpc.layered(root_files, &[(probe.to_string(), text.join("\n"))]).await {
140	        Ok(layered) => Arc::new(layered),
141	        Err(CallError::Rejected(message)) => {
142	            all_fall_back(&mut outcome, &format!("the checker could not instantiate a generic component: {message}"));
143	            return Ok(outcome);
144	        }
145	        Err(fatal) => return Err(fatal),
146	    };
147	    let answered = answer_layered(&layered, probe.as_str(), interner, reverse, &pending).await;
148	    layered.release().await;
149	    match answered {
150	        Ok(answered) => Ok(answered),
151	        Err(CallError::Rejected(message)) => {
152	            all_fall_back(&mut outcome, &format!("the checker rejected a request: {message}"));
153	            Ok(outcome)
154	        }
155	        Err(fatal) => Err(fatal),
156	    }
157	}
