159	async fn answer_layered(
160	    layered: &Arc<Rpc>,
161	    probe: &str,
162	    interner: &PropInterner,
163	    reverse: bool,
164	    pending: &[(Target, Instantiation)],
165	) -> Result<SemanticOutcome, CallError> {
166	    let mut outcome = SemanticOutcome::default();
167	    let Some(module) = layered.source_file_symbol(probe).await? else {
168	        let reason = "the checker did not load the file that instantiates generic components";
169	        outcome.fallbacks.extend(pending.iter().map(|(target, _)| fallback_of(target, reason)));
170	        return Ok(outcome);
171	    };
172	    let probes: FxHashMap<String, SymbolRef> = layered
173	        .exports_of_module(&module.reference)
174	        .await?
175	        .into_iter()
176	        .map(|symbol| (symbol.name, symbol.reference))
177	        .collect();
178	    let mut errors: FxHashMap<usize, String> = FxHashMap::default();
179	    // The checker's answer for a file also holds errors it found in other files while forming the instantiations; a
180	    // line number says nothing about those, so only the probe file's own errors are the errors of a probe line.
181	    let in_probe = |diagnostic: &FileDiagnostic| diagnostic.file_name.replace('\\', "/") == probe.replace('\\', "/");
182	    for diagnostic in layered.semantic_diagnostics(probe).await?.into_iter().filter(|d| d.is_error() && in_probe(d)) {
183	        errors.entry(diagnostic.start_position.line).or_insert_with(|| diagnostic.message());
184	    }
185	
186	    let converter = Converter::new(layered.clone(), reverse);
187	    for (index, (target, instantiation)) in pending.iter().enumerate() {
188	        let read = match (errors.get(&index), probes.get(&format!("CaliperProbe{index}"))) {
189	            (Some(error), _) => {
190	                Err(format!("the instantiation {} could not be formed: {error}", written(target, instantiation)))
191	            }
192	            (None, None) => Err(format!("the instantiation {} was not declared", written(target, instantiation))),
193	            (None, Some(symbol)) => {
194	                let kept = arguments_keep_their_meaning(layered, &probes, index, instantiation).await;
195	                match kept {
196	                    Ok(false) => Err(format!(
197	                        "the instantiation {} could not be formed: a name in its type arguments means something \
198	                         else where the instantiation is written than in the component's module",
199	                        written(target, instantiation)
200	                    )),
201	                    Ok(true) => match read_probe(layered, &converter, interner, symbol, target).await {
202	                        Ok(read) => read,
203	                        Err(CallError::Rejected(message)) => Err(format!("the checker rejected a request: {message}")),
204	                        Err(fatal) => return Err(fatal),
205	                    },
206	                    Err(CallError::Rejected(message)) => Err(format!("the checker rejected a request: {message}")),
207	                    Err(fatal) => return Err(fatal),
208	                }
209	            }
210	        };
211	        match read {
212	            Ok(component::Props { props, composes, whole }) => {
213	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes, whole });
214	            }
215	            Err(reason) => outcome.fallbacks.push(fallback_of(target, &reason)),
216	        }
217	    }
218	    Ok(outcome)
219	}
