221	async fn read_probe(
222	    layered: &Rpc,
223	    converter: &Converter,
224	    interner: &PropInterner,
225	    symbol: &SymbolRef,
226	    target: &Target,
227	) -> Result<Result<component::Props, String>, CallError> {
228	    let props_type = layered.declared_type_of_symbol(symbol).await?;
229	    component::props_of_type(layered, converter, interner, &props_type, target).await
230	}
